Refactor this Express route so the lending rules no longer depend on Express or PostgreSQL:

```typescript
app.post('/api/loans', async (req, res) => {
  const { memberId, bookId } = req.body;
  const member = await pool.query('SELECT * FROM members WHERE id = $1', [memberId]);
  if (member.rows.length === 0) return res.status(404).json({ error: 'Member not found' });
  if (member.rows[0].unpaid_fees > 10) {
    return res.status(403).json({ error: 'Outstanding fees' });
  }
  const active = await pool.query(
    'SELECT COUNT(*) FROM loans WHERE member_id = $1 AND returned_at IS NULL', [memberId]);
  if (Number(active.rows[0].count) >= 5) {
    return res.status(409).json({ error: 'Loan limit reached' });
  }
  const due = new Date(Date.now() + 21 * 24 * 60 * 60 * 1000);
  await pool.query('INSERT INTO loans (member_id, book_id, due_at) VALUES ($1, $2, $3)',
    [memberId, bookId, due]);
  res.status(201).json({ dueAt: due });
});
```

### Architectural Flaws in Original Code
1. **Business rules inside the HTTP handler:** the fee ceiling (10), the loan limit (5) and the 21-day period are hidden in a route callback.
2. **SQL in the controller:** the rules cannot run or be tested without PostgreSQL.
3. **Clock coupling:** `Date.now()` is called directly, so the due date is not deterministic in tests.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Member.ts`)
```typescript
import { Result } from '../shared/Result';

export type LoanError =
  | { kind: 'MemberNotFound' }
  | { kind: 'OutstandingFees'; amount: number }
  | { kind: 'LoanLimitReached'; limit: number };

export class Member {
  static readonly MAX_FEES = 10;
  static readonly MAX_ACTIVE_LOANS = 5;
  static readonly LOAN_DAYS = 21;

  constructor(
    readonly id: string,
    readonly unpaidFees: number,
    readonly activeLoans: number,
  ) {}

  borrow(bookId: string, now: Date): Result<Loan, LoanError> {
    if (this.unpaidFees > Member.MAX_FEES) {
      return Result.fail({ kind: 'OutstandingFees', amount: this.unpaidFees });
    }
    if (this.activeLoans >= Member.MAX_ACTIVE_LOANS) {
      return Result.fail({ kind: 'LoanLimitReached', limit: Member.MAX_ACTIVE_LOANS });
    }
    const dueAt = new Date(now.getTime() + Member.LOAN_DAYS * 24 * 60 * 60 * 1000);
    return Result.ok({ memberId: this.id, bookId, dueAt });
  }
}

export interface Loan {
  readonly memberId: string;
  readonly bookId: string;
  readonly dueAt: Date;
}
```

#### 2. Application Layer (`src/application/BorrowBook.ts`)
```typescript
import { Result } from '../shared/Result';
import { Loan, LoanError, Member } from '../domain/Member';

export interface MemberRepository {
  findById(id: string): Promise<Member | null>;
}

export interface LoanRepository {
  save(loan: Loan): Promise<void>;
}

export interface Clock {
  now(): Date;
}

export class BorrowBook {
  constructor(
    private readonly members: MemberRepository,
    private readonly loans: LoanRepository,
    private readonly clock: Clock,
  ) {}

  async execute(input: { memberId: string; bookId: string }): Promise<Result<Loan, LoanError>> {
    const member = await this.members.findById(input.memberId);
    if (!member) return Result.fail({ kind: 'MemberNotFound' });

    const loan = member.borrow(input.bookId, this.clock.now());
    if (!loan.success) return loan;

    await this.loans.save(loan.data);
    return loan;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/PostgresLibrary.ts`)
```typescript
import { Pool } from 'pg';
import { Loan, Member } from '../domain/Member';
import { LoanRepository, MemberRepository } from '../application/BorrowBook';

export class PostgresMemberRepository implements MemberRepository {
  constructor(private readonly pool: Pool) {}

  async findById(id: string): Promise<Member | null> {
    const member = await this.pool.query('SELECT unpaid_fees FROM members WHERE id = $1', [id]);
    if (member.rows.length === 0) return null;
    const active = await this.pool.query(
      'SELECT COUNT(*) FROM loans WHERE member_id = $1 AND returned_at IS NULL', [id]);
    return new Member(id, Number(member.rows[0].unpaid_fees), Number(active.rows[0].count));
  }
}

export class PostgresLoanRepository implements LoanRepository {
  constructor(private readonly pool: Pool) {}

  async save(loan: Loan): Promise<void> {
    await this.pool.query('INSERT INTO loans (member_id, book_id, due_at) VALUES ($1, $2, $3)',
      [loan.memberId, loan.bookId, loan.dueAt]);
  }
}
```

#### 4. Presentation Layer (thin controller)
```typescript
function toHttp(error: LoanError): { status: number; message: string } {
  switch (error.kind) {
    case 'MemberNotFound': return { status: 404, message: 'Member not found' };
    case 'OutstandingFees': return { status: 403, message: 'Outstanding fees' };
    case 'LoanLimitReached': return { status: 409, message: 'Loan limit reached' };
  }
}

app.post('/api/loans', async (req, res) => {
  const result = await borrowBook.execute({ memberId: req.body.memberId, bookId: req.body.bookId });
  if (!result.success) {
    const { status, message } = toHttp(result.error);
    return res.status(status).json({ error: message });
  }
  res.status(201).json({ dueAt: result.data.dueAt });
});
```

This NestJS controller reserves warehouse stock but every rule sits next to TypeORM calls. Refactor it to Clean Architecture:

```typescript
@Controller('reservations')
export class ReservationController {
  constructor(
    @InjectRepository(StockItem) private stock: Repository<StockItem>,
    @InjectRepository(Reservation) private reservations: Repository<Reservation>,
  ) {}

  @Post()
  async reserve(@Body() body: { sku: string; quantity: number }) {
    if (!Number.isInteger(body.quantity) || body.quantity <= 0) {
      throw new BadRequestException('Quantity must be a positive integer');
    }
    const item = await this.stock.findOne({ where: { sku: body.sku } });
    if (!item) throw new NotFoundException('Unknown SKU');
    const available = item.onHand - item.reserved;
    if (available < body.quantity) {
      throw new ConflictException(`Only ${available} units available`);
    }
    item.reserved += body.quantity;
    await this.stock.save(item);
    return this.reservations.save({ sku: body.sku, quantity: body.quantity, createdAt: new Date() });
  }
}
```

### Architectural Flaws in Original Code
1. **Framework exceptions as business errors:** `BadRequestException` and `ConflictException` tie the reservation rules to NestJS.
2. **ORM entities as domain model:** the availability calculation mutates a TypeORM row in the controller.
3. **No atomic boundary:** the stock update and the reservation insert are two unrelated saves.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/StockItem.ts`)
```typescript
import { Result } from '../shared/Result';

export type ReservationError =
  | { kind: 'InvalidQuantity' }
  | { kind: 'UnknownSku'; sku: string }
  | { kind: 'InsufficientStock'; available: number };

export class StockItem {
  constructor(
    readonly sku: string,
    readonly onHand: number,
    private reservedUnits: number,
  ) {}

  get reserved(): number {
    return this.reservedUnits;
  }

  get available(): number {
    return this.onHand - this.reservedUnits;
  }

  reserve(quantity: number): Result<void, ReservationError> {
    if (!Number.isInteger(quantity) || quantity <= 0) {
      return Result.fail({ kind: 'InvalidQuantity' });
    }
    if (this.available < quantity) {
      return Result.fail({ kind: 'InsufficientStock', available: this.available });
    }
    this.reservedUnits += quantity;
    return Result.ok(undefined);
  }
}
```

#### 2. Application Layer (`src/application/ReserveStock.ts`)
```typescript
import { Result } from '../shared/Result';
import { ReservationError, StockItem } from '../domain/StockItem';

export interface StockReservation {
  readonly sku: string;
  readonly quantity: number;
  readonly createdAt: Date;
}

export interface StockStore {
  findBySku(sku: string): Promise<StockItem | null>;
  /** Persists the item and the reservation in one transaction. */
  commit(item: StockItem, reservation: StockReservation): Promise<void>;
}

export class ReserveStock {
  constructor(private readonly store: StockStore, private readonly now: () => Date) {}

  async execute(sku: string, quantity: number): Promise<Result<StockReservation, ReservationError>> {
    const item = await this.store.findBySku(sku);
    if (!item) return Result.fail({ kind: 'UnknownSku', sku });

    const reserved = item.reserve(quantity);
    if (!reserved.success) return reserved;

    const reservation: StockReservation = { sku, quantity, createdAt: this.now() };
    await this.store.commit(item, reservation);
    return Result.ok(reservation);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/TypeOrmStockStore.ts`)
```typescript
import { DataSource } from 'typeorm';
import { StockItem } from '../domain/StockItem';
import { StockReservation, StockStore } from '../application/ReserveStock';
import { StockItemRow, ReservationRow } from './rows';

export class TypeOrmStockStore implements StockStore {
  constructor(private readonly db: DataSource) {}

  async findBySku(sku: string): Promise<StockItem | null> {
    const row = await this.db.getRepository(StockItemRow).findOne({ where: { sku } });
    return row ? new StockItem(row.sku, row.onHand, row.reserved) : null;
  }

  async commit(item: StockItem, reservation: StockReservation): Promise<void> {
    await this.db.transaction(async (tx) => {
      await tx.getRepository(StockItemRow).update({ sku: item.sku }, { reserved: item.reserved });
      await tx.getRepository(ReservationRow).insert({ ...reservation });
    });
  }
}
```

#### 4. Presentation Layer (NestJS controller)
```typescript
import { BadRequestException, Body, ConflictException, Controller, NotFoundException, Post } from '@nestjs/common';
import { ReserveStock } from '../application/ReserveStock';

@Controller('reservations')
export class ReservationController {
  constructor(private readonly reserveStock: ReserveStock) {}

  @Post()
  async reserve(@Body() body: { sku: string; quantity: number }) {
    const result = await this.reserveStock.execute(body.sku, body.quantity);
    if (result.success) return result.data;
    const error = result.error;
    switch (error.kind) {
      case 'InvalidQuantity':
        throw new BadRequestException('Quantity must be a positive integer');
      case 'UnknownSku':
        throw new NotFoundException('Unknown SKU');
      case 'InsufficientStock':
        throw new ConflictException(`Only ${error.available} units available`);
    }
  }
}
```

NestJS exceptions now live only at the edge; the domain reports failures as typed values.

Refactor this React component. The shipping cost rules are mixed with fetching and rendering:

```tsx
export function ShippingQuote({ cartId }: { cartId: string }) {
  const [cart, setCart] = useState<{ weightKg: number; subtotal: number; country: string } | null>(null);

  useEffect(() => {
    axios.get(`/api/carts/${cartId}`).then((r) => setCart(r.data));
  }, [cartId]);

  if (!cart) return <p>Loading…</p>;

  let cost = 0;
  if (cart.subtotal >= 75) cost = 0;
  else if (cart.weightKg <= 1) cost = 4.99;
  else if (cart.weightKg <= 5) cost = 8.99;
  else cost = 8.99 + Math.ceil(cart.weightKg - 5) * 1.5;
  if (cart.country !== 'US' && cart.subtotal < 75) cost += 12;

  return <p>Shipping: {cost === 0 ? 'Free' : `$${cost.toFixed(2)}`}</p>;
}
```

### Architectural Flaws in Original Code
1. **Pricing rules inside a render function:** the free-shipping threshold, weight tiers and international surcharge can only be tested by rendering React.
2. **Transport in the view:** `axios` is called from the component, so the UI cannot be reused with another data source.
3. **Untyped response:** `r.data` is trusted as the cart shape without validation.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/shipping.ts`)
Pure function, no React, no HTTP.
```typescript
export interface CartSummary {
  readonly weightKg: number;
  readonly subtotal: number;
  readonly country: string;
}

export const FREE_SHIPPING_THRESHOLD = 75;
const INTERNATIONAL_SURCHARGE = 12;

export function shippingCost(cart: CartSummary): number {
  if (cart.subtotal >= FREE_SHIPPING_THRESHOLD) return 0;
  let cost: number;
  if (cart.weightKg <= 1) cost = 4.99;
  else if (cart.weightKg <= 5) cost = 8.99;
  else cost = 8.99 + Math.ceil(cart.weightKg - 5) * 1.5;
  if (cart.country !== 'US') cost += INTERNATIONAL_SURCHARGE;
  return cost;
}
```

#### 2. Application Layer (`src/application/getShippingQuote.ts`)
```typescript
import { Result } from '../shared/Result';
import { CartSummary, shippingCost } from '../domain/shipping';

export type QuoteError = { kind: 'CartUnavailable'; cartId: string };

export interface CartReader {
  summary(cartId: string): Promise<CartSummary | null>;
}

export async function getShippingQuote(
  carts: CartReader,
  cartId: string,
): Promise<Result<number, QuoteError>> {
  const cart = await carts.summary(cartId);
  if (!cart) return Result.fail({ kind: 'CartUnavailable', cartId });
  return Result.ok(shippingCost(cart));
}
```

#### 3. Infrastructure Layer (`src/infrastructure/HttpCartReader.ts`)
```typescript
import axios from 'axios';
import { CartSummary } from '../domain/shipping';
import { CartReader } from '../application/getShippingQuote';

function isCartSummary(value: unknown): value is CartSummary {
  if (typeof value !== 'object' || value === null) return false;
  const v = value as Record<string, unknown>;
  return typeof v.weightKg === 'number' && typeof v.subtotal === 'number' && typeof v.country === 'string';
}

export class HttpCartReader implements CartReader {
  async summary(cartId: string): Promise<CartSummary | null> {
    const response = await axios.get<unknown>(`/api/carts/${cartId}`);
    return isCartSummary(response.data) ? response.data : null;
  }
}
```

#### 4. Presentation Layer (`src/ui/ShippingQuote.tsx`)
The component receives the reader and only renders.
```tsx
export function ShippingQuote({ cartId, carts }: { cartId: string; carts: CartReader }) {
  const [quote, setQuote] = useState<Result<number, QuoteError> | null>(null);

  useEffect(() => {
    getShippingQuote(carts, cartId).then(setQuote);
  }, [cartId, carts]);

  if (!quote) return <p>Loading…</p>;
  if (!quote.success) return <p>Shipping unavailable</p>;
  return <p>Shipping: {quote.data === 0 ? 'Free' : `$${quote.data.toFixed(2)}`}</p>;
}
```

`shippingCost` can now be unit-tested with plain objects, for example `{ weightKg: 7.2, subtotal: 40, country: 'CA' }` → `8.99 + 3 * 1.5 + 12 = 25.49`.

Clean up this Fastify handler. Coupon rules, Redis keys and the HTTP reply are all in one place:

```typescript
fastify.post('/coupons/redeem', async (request, reply) => {
  const { code, customerId, orderTotal } = request.body as {
    code: string; customerId: string; orderTotal: number;
  };
  const raw = await redis.get(`coupon:${code.toUpperCase()}`);
  if (!raw) return reply.code(404).send({ error: 'Invalid coupon' });
  const coupon = JSON.parse(raw);
  if (new Date(coupon.expiresAt) < new Date()) return reply.code(410).send({ error: 'Coupon expired' });
  if (orderTotal < coupon.minOrder) return reply.code(422).send({ error: 'Order too small' });
  const used = await redis.sismember(`coupon:${code.toUpperCase()}:used`, customerId);
  if (used) return reply.code(409).send({ error: 'Already redeemed' });
  const discount = coupon.type === 'percent'
    ? Math.min(orderTotal * coupon.value / 100, coupon.maxDiscount ?? Infinity)
    : Math.min(coupon.value, orderTotal);
  await redis.sadd(`coupon:${code.toUpperCase()}:used`, customerId);
  return { discount: Math.round(discount * 100) / 100 };
});
```

### Architectural Flaws in Original Code
1. **Discount math in the transport layer:** percent caps and fixed-amount rules are buried in a Fastify callback.
2. **Storage format leaks:** Redis key naming and `JSON.parse` of an untyped blob live next to business decisions.
3. **Implicit time:** `new Date()` makes expiry impossible to test deterministically.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Coupon.ts`)
```typescript
import { Result } from '../shared/Result';

export type CouponError =
  | { kind: 'NotFound' }
  | { kind: 'Expired' }
  | { kind: 'BelowMinimum'; minOrder: number }
  | { kind: 'AlreadyRedeemed' };

export type DiscountRule =
  | { type: 'percent'; value: number; maxDiscount?: number }
  | { type: 'fixed'; value: number };

export class Coupon {
  constructor(
    readonly code: string,
    readonly rule: DiscountRule,
    readonly minOrder: number,
    readonly expiresAt: Date,
  ) {}

  static normalize(code: string): string { return code.toUpperCase(); }

  discountFor(orderTotal: number, now: Date): Result<number, CouponError> {
    if (this.expiresAt < now) return Result.fail({ kind: 'Expired' });
    if (orderTotal < this.minOrder) return Result.fail({ kind: 'BelowMinimum', minOrder: this.minOrder });
    const raw = this.rule.type === 'percent'
      ? Math.min((orderTotal * this.rule.value) / 100, this.rule.maxDiscount ?? Infinity)
      : Math.min(this.rule.value, orderTotal);
    return Result.ok(Math.round(raw * 100) / 100);
  }
}
```

#### 2. Application Layer (`src/application/RedeemCoupon.ts`)
```typescript
import { Result } from '../shared/Result';
import { Coupon, CouponError } from '../domain/Coupon';

export interface CouponRepository {
  find(code: string): Promise<Coupon | null>;
  hasRedeemed(code: string, customerId: string): Promise<boolean>;
  markRedeemed(code: string, customerId: string): Promise<void>;
}

export class RedeemCoupon {
  constructor(private readonly coupons: CouponRepository, private readonly now: () => Date) {}

  async execute(input: { code: string; customerId: string; orderTotal: number }): Promise<Result<number, CouponError>> {
    const code = Coupon.normalize(input.code);
    const coupon = await this.coupons.find(code);
    if (!coupon) return Result.fail({ kind: 'NotFound' });

    const discount = coupon.discountFor(input.orderTotal, this.now());
    if (!discount.success) return discount;

    if (await this.coupons.hasRedeemed(code, input.customerId)) {
      return Result.fail({ kind: 'AlreadyRedeemed' });
    }
    await this.coupons.markRedeemed(code, input.customerId);
    return discount;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/RedisCouponRepository.ts`)
```typescript
import type { Redis } from 'ioredis';
import { Coupon, DiscountRule } from '../domain/Coupon';
import { CouponRepository } from '../application/RedeemCoupon';

interface StoredCoupon {
  type: 'percent' | 'fixed';
  value: number;
  maxDiscount?: number;
  minOrder: number;
  expiresAt: string;
}

export class RedisCouponRepository implements CouponRepository {
  constructor(private readonly redis: Redis) {}

  async find(code: string): Promise<Coupon | null> {
    const raw = await this.redis.get(`coupon:${code}`);
    if (!raw) return null;
    const stored = JSON.parse(raw) as StoredCoupon;
    const rule: DiscountRule = stored.type === 'percent'
      ? { type: 'percent', value: stored.value, maxDiscount: stored.maxDiscount }
      : { type: 'fixed', value: stored.value };
    return new Coupon(code, rule, stored.minOrder, new Date(stored.expiresAt));
  }

  async hasRedeemed(code: string, customerId: string): Promise<boolean> {
    return (await this.redis.sismember(`coupon:${code}:used`, customerId)) === 1;
  }

  async markRedeemed(code: string, customerId: string): Promise<void> {
    await this.redis.sadd(`coupon:${code}:used`, customerId);
  }
}
```

#### 4. Presentation Layer (Fastify route)
```typescript
function toHttp(error: CouponError): [number, string] {
  switch (error.kind) {
    case 'NotFound': return [404, 'Invalid coupon'];
    case 'Expired': return [410, 'Coupon expired'];
    case 'BelowMinimum': return [422, 'Order too small'];
    case 'AlreadyRedeemed': return [409, 'Already redeemed'];
  }
}

fastify.post<{ Body: { code: string; customerId: string; orderTotal: number } }>(
  '/coupons/redeem',
  async (request, reply) => {
    const result = await redeemCoupon.execute(request.body);
    if (result.success) return { discount: result.data };
    const [status, error] = toHttp(result.error);
    return reply.code(status).send({ error });
  },
);
```

Refactor this Kafka consumer so invoice settlement rules can be tested without Kafka or MongoDB:

```typescript
await consumer.run({
  eachMessage: async ({ message }) => {
    const evt = JSON.parse(message.value!.toString());
    const invoices = mongo.db('billing').collection('invoices');
    const invoice = await invoices.findOne({ _id: evt.invoiceId });
    if (!invoice || invoice.status === 'void') return;
    const paid = invoice.paid + evt.amountCents;
    let status = 'partially_paid';
    if (paid >= invoice.totalCents) status = 'paid';
    await invoices.updateOne(
      { _id: evt.invoiceId },
      { $set: { paid, status }, $push: { payments: { ref: evt.paymentRef, amount: evt.amountCents } } },
    );
    if (paid > invoice.totalCents) {
      await producer.send({ topic: 'refunds', messages: [{ value: JSON.stringify({
        invoiceId: evt.invoiceId, amountCents: paid - invoice.totalCents }) }] });
    }
  },
});
```

### Architectural Flaws in Original Code
1. **Settlement logic in the message loop:** status transitions and overpayment detection are tied to `kafkajs` callbacks.
2. **Untyped event:** the payload is `JSON.parse`d and used without validation.
3. **Silent idempotency gap:** a redelivered message is applied twice because the payment reference is never checked.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Invoice.ts`)
```typescript
import { Result } from '../shared/Result';

export type InvoiceStatus = 'open' | 'partially_paid' | 'paid' | 'void';
export type SettlementError = { kind: 'InvoiceVoid' } | { kind: 'DuplicatePayment'; ref: string };

export interface Payment { readonly ref: string; readonly amountCents: number; }

export class Invoice {
  constructor(
    readonly id: string,
    readonly totalCents: number,
    private paidCents: number,
    private currentStatus: InvoiceStatus,
    private readonly payments: Payment[],
  ) {}

  get paid(): number { return this.paidCents; }
  get status(): InvoiceStatus { return this.currentStatus; }

  /** Applies a payment and returns the overpaid amount in cents (0 if none). */
  apply(payment: Payment): Result<number, SettlementError> {
    if (this.currentStatus === 'void') return Result.fail({ kind: 'InvoiceVoid' });
    if (this.payments.some((p) => p.ref === payment.ref)) {
      return Result.fail({ kind: 'DuplicatePayment', ref: payment.ref });
    }
    this.payments.push(payment);
    this.paidCents += payment.amountCents;
    this.currentStatus = this.paidCents >= this.totalCents ? 'paid' : 'partially_paid';
    return Result.ok(Math.max(0, this.paidCents - this.totalCents));
  }
}
```

#### 2. Application Layer (`src/application/SettleInvoice.ts`)
```typescript
import { Result } from '../shared/Result';
import { Invoice, Payment, SettlementError } from '../domain/Invoice';

export type SettleError = SettlementError | { kind: 'InvoiceNotFound' };

export interface InvoiceRepository {
  findById(id: string): Promise<Invoice | null>;
  recordPayment(invoice: Invoice, payment: Payment): Promise<void>;
}

export interface RefundRequester {
  request(invoiceId: string, amountCents: number): Promise<void>;
}

export class SettleInvoice {
  constructor(private readonly invoices: InvoiceRepository, private readonly refunds: RefundRequester) {}

  async execute(invoiceId: string, payment: Payment): Promise<Result<void, SettleError>> {
    const invoice = await this.invoices.findById(invoiceId);
    if (!invoice) return Result.fail({ kind: 'InvoiceNotFound' });

    const overpaid = invoice.apply(payment);
    if (!overpaid.success) return overpaid;

    await this.invoices.recordPayment(invoice, payment);
    if (overpaid.data > 0) await this.refunds.request(invoiceId, overpaid.data);
    return Result.ok(undefined);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure`)
```typescript
import { Collection } from 'mongodb';
import { Producer } from 'kafkajs';
import { Invoice, InvoiceStatus, Payment } from '../domain/Invoice';
import { InvoiceRepository, RefundRequester } from '../application/SettleInvoice';

interface InvoiceDoc {
  _id: string; totalCents: number; paid: number; status: InvoiceStatus;
  payments: { ref: string; amount: number }[];
}

export class MongoInvoiceRepository implements InvoiceRepository {
  constructor(private readonly invoices: Collection<InvoiceDoc>) {}

  async findById(id: string): Promise<Invoice | null> {
    const doc = await this.invoices.findOne({ _id: id });
    if (!doc) return null;
    const payments = doc.payments.map((p) => ({ ref: p.ref, amountCents: p.amount }));
    return new Invoice(doc._id, doc.totalCents, doc.paid, doc.status, payments);
  }

  async recordPayment(invoice: Invoice, payment: Payment): Promise<void> {
    await this.invoices.updateOne(
      { _id: invoice.id },
      { $set: { paid: invoice.paid, status: invoice.status },
        $push: { payments: { ref: payment.ref, amount: payment.amountCents } } },
    );
  }
}

export class KafkaRefundRequester implements RefundRequester {
  constructor(private readonly producer: Producer) {}

  async request(invoiceId: string, amountCents: number): Promise<void> {
    await this.producer.send({ topic: 'refunds', messages: [{ value: JSON.stringify({ invoiceId, amountCents }) }] });
  }
}
```

#### 4. Entry Point (consumer)
Malformed messages are rejected at the edge by a type guard.
```typescript
import { EachMessagePayload } from 'kafkajs';

interface PaymentSettled { invoiceId: string; paymentRef: string; amountCents: number; }

function isPaymentSettled(v: unknown): v is PaymentSettled {
  if (typeof v !== 'object' || v === null) return false;
  const e = v as Record<string, unknown>;
  return typeof e.invoiceId === 'string' && typeof e.paymentRef === 'string' && typeof e.amountCents === 'number';
}

await consumer.run({
  eachMessage: async ({ message }: EachMessagePayload) => {
    const evt: unknown = JSON.parse(message.value?.toString() ?? 'null');
    if (!isPaymentSettled(evt)) return;
    await settleInvoice.execute(evt.invoiceId, { ref: evt.paymentRef, amountCents: evt.amountCents });
  },
});
```

This Node.js script computes weekly pay. Move it to a layered TypeScript design where the pay rules don't touch the filesystem:

```javascript
const fs = require('fs');

const shifts = JSON.parse(fs.readFileSync('./shifts.json', 'utf8'));
const rates = JSON.parse(fs.readFileSync('./rates.json', 'utf8'));
const byEmployee = {};
for (const s of shifts) {
  const hours = (new Date(s.end) - new Date(s.start)) / 3600000;
  byEmployee[s.employeeId] = (byEmployee[s.employeeId] || 0) + hours;
}
const lines = ['employee,regular,overtime,gross'];
for (const id of Object.keys(byEmployee)) {
  const total = byEmployee[id];
  const regular = Math.min(total, 40);
  const overtime = Math.max(0, total - 40);
  const gross = regular * rates[id] + overtime * rates[id] * 1.5;
  lines.push(`${id},${regular.toFixed(2)},${overtime.toFixed(2)},${gross.toFixed(2)}`);
}
fs.writeFileSync('./payroll.csv', lines.join('\n'));
```

### Architectural Flaws in Original Code
1. **Pay rules mixed with I/O:** the 40-hour threshold and the 1.5× overtime multiplier sit between `readFileSync` and `writeFileSync`.
2. **Missing rate is silent:** an employee without a rate produces `NaN` in the CSV.
3. **Output format coupled to calculation:** CSV formatting is interleaved with the arithmetic.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/payroll.ts`)
```typescript
export interface Shift {
  readonly employeeId: string;
  readonly start: Date;
  readonly end: Date;
}

export interface PayLine {
  readonly employeeId: string;
  readonly regularHours: number;
  readonly overtimeHours: number;
  readonly gross: number;
}

export const REGULAR_WEEK_HOURS = 40;
export const OVERTIME_MULTIPLIER = 1.5;

export function hoursByEmployee(shifts: readonly Shift[]): Map<string, number> {
  const totals = new Map<string, number>();
  for (const s of shifts) {
    const hours = (s.end.getTime() - s.start.getTime()) / 3_600_000;
    totals.set(s.employeeId, (totals.get(s.employeeId) ?? 0) + hours);
  }
  return totals;
}

export function payFor(employeeId: string, hours: number, hourlyRate: number): PayLine {
  const regularHours = Math.min(hours, REGULAR_WEEK_HOURS);
  const overtimeHours = Math.max(0, hours - REGULAR_WEEK_HOURS);
  const gross = regularHours * hourlyRate + overtimeHours * hourlyRate * OVERTIME_MULTIPLIER;
  return { employeeId, regularHours, overtimeHours, gross };
}
```

#### 2. Application Layer (`src/application/RunPayroll.ts`)
```typescript
import { Result } from '../shared/Result';
import { PayLine, Shift, hoursByEmployee, payFor } from '../domain/payroll';

export type PayrollError = { kind: 'MissingRate'; employeeIds: string[] };

export interface TimesheetSource {
  shifts(): Promise<Shift[]>;
  hourlyRates(): Promise<Map<string, number>>;
}

export interface PayrollSink {
  write(lines: readonly PayLine[]): Promise<void>;
}

export class RunPayroll {
  constructor(private readonly source: TimesheetSource, private readonly sink: PayrollSink) {}

  async execute(): Promise<Result<PayLine[], PayrollError>> {
    const [shifts, rates] = await Promise.all([this.source.shifts(), this.source.hourlyRates()]);
    const totals = hoursByEmployee(shifts);

    const missing = [...totals.keys()].filter((id) => !rates.has(id));
    if (missing.length > 0) return Result.fail({ kind: 'MissingRate', employeeIds: missing });

    const lines = [...totals].map(([id, hours]) => payFor(id, hours, rates.get(id) ?? 0));
    await this.sink.write(lines);
    return Result.ok(lines);
  }
}
```
A missing rate is now an explicit error instead of `NaN` in the output.

#### 3. Infrastructure Layer (`src/infrastructure/files.ts`)
```typescript
import { readFile, writeFile } from 'node:fs/promises';
import { PayLine, Shift } from '../domain/payroll';
import { PayrollSink, TimesheetSource } from '../application/RunPayroll';

interface ShiftRecord { employeeId: string; start: string; end: string; }

export class JsonTimesheetSource implements TimesheetSource {
  constructor(private readonly shiftsPath: string, private readonly ratesPath: string) {}

  async shifts(): Promise<Shift[]> {
    const records = JSON.parse(await readFile(this.shiftsPath, 'utf8')) as ShiftRecord[];
    return records.map((r) => ({ employeeId: r.employeeId, start: new Date(r.start), end: new Date(r.end) }));
  }

  async hourlyRates(): Promise<Map<string, number>> {
    const rates = JSON.parse(await readFile(this.ratesPath, 'utf8')) as Record<string, number>;
    return new Map(Object.entries(rates));
  }
}

export class CsvPayrollSink implements PayrollSink {
  constructor(private readonly path: string) {}

  async write(lines: readonly PayLine[]): Promise<void> {
    const rows = lines.map((l) =>
      [l.employeeId, l.regularHours.toFixed(2), l.overtimeHours.toFixed(2), l.gross.toFixed(2)].join(','));
    await writeFile(this.path, ['employee,regular,overtime,gross', ...rows].join('\n'));
  }
}
```

#### 4. Composition Root (`src/main.ts`)
```typescript
const payroll = new RunPayroll(
  new JsonTimesheetSource('./shifts.json', './rates.json'),
  new CsvPayrollSink('./payroll.csv'),
);
const result = await payroll.execute();
if (!result.success) {
  console.error(`No hourly rate for: ${result.error.employeeIds.join(', ')}`);
  process.exitCode = 1;
}
```

Restructure this renewal job using Clean Architecture. Billing rules, Stripe and Sequelize are tangled together:

```typescript
cron.schedule('0 3 * * *', async () => {
  const due = await Subscription.findAll({
    where: { status: 'active', renewsAt: { [Op.lte]: new Date() } },
  });
  for (const sub of due) {
    try {
      await stripe.paymentIntents.create({
        amount: sub.priceCents, currency: 'usd', customer: sub.stripeCustomerId,
        payment_method: sub.defaultPaymentMethod, off_session: true, confirm: true,
      });
      const next = new Date(sub.renewsAt);
      next.setMonth(next.getMonth() + (sub.interval === 'yearly' ? 12 : 1));
      await sub.update({ renewsAt: next, failedAttempts: 0 });
    } catch (e) {
      const attempts = sub.failedAttempts + 1;
      await sub.update({ failedAttempts: attempts, status: attempts >= 3 ? 'past_due' : 'active' });
    }
  }
});
```

### Architectural Flaws in Original Code
1. **Renewal policy hidden in a cron callback:** the billing interval and the three-strike rule cannot be tested without Stripe and a database.
2. **Active Record models as domain:** `sub.update(...)` couples state changes to Sequelize.
3. **Exceptions as control flow:** any error, including a bug, is counted as a failed charge.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Subscription.ts`)
```typescript
export type BillingInterval = 'monthly' | 'yearly';
export type SubscriptionStatus = 'active' | 'past_due';

export class Subscription {
  static readonly MAX_FAILED_ATTEMPTS = 3;

  constructor(
    readonly id: string,
    readonly customerRef: string,
    readonly paymentMethodRef: string,
    readonly priceCents: number,
    readonly interval: BillingInterval,
    private renewal: Date,
    private failures: number,
    private state: SubscriptionStatus,
  ) {}

  get renewsAt(): Date { return this.renewal; }
  get failedAttempts(): number { return this.failures; }
  get status(): SubscriptionStatus { return this.state; }

  renewed(): void {
    const next = new Date(this.renewal);
    next.setMonth(next.getMonth() + (this.interval === 'yearly' ? 12 : 1));
    this.renewal = next;
    this.failures = 0;
  }

  chargeFailed(): void {
    this.failures += 1;
    if (this.failures >= Subscription.MAX_FAILED_ATTEMPTS) this.state = 'past_due';
  }
}
```

#### 2. Application Layer (`src/application/RenewDueSubscriptions.ts`)
```typescript
import { Result } from '../shared/Result';
import { Subscription } from '../domain/Subscription';

export type ChargeError = { kind: 'Declined'; reason: string };

export interface SubscriptionRepository {
  findDue(asOf: Date): Promise<Subscription[]>;
  save(subscription: Subscription): Promise<void>;
}

export interface PaymentProcessor {
  charge(customerRef: string, paymentMethodRef: string, amountCents: number): Promise<Result<void, ChargeError>>;
}

export class RenewDueSubscriptions {
  constructor(
    private readonly subscriptions: SubscriptionRepository,
    private readonly payments: PaymentProcessor,
    private readonly now: () => Date,
  ) {}

  async execute(): Promise<{ renewed: number; failed: number }> {
    let renewed = 0;
    let failed = 0;
    for (const sub of await this.subscriptions.findDue(this.now())) {
      const charge = await this.payments.charge(sub.customerRef, sub.paymentMethodRef, sub.priceCents);
      if (charge.success) { sub.renewed(); renewed++; } else { sub.chargeFailed(); failed++; }
      await this.subscriptions.save(sub);
    }
    return { renewed, failed };
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/StripePaymentProcessor.ts`)
```typescript
import Stripe from 'stripe';
import { Result } from '../shared/Result';
import { ChargeError, PaymentProcessor } from '../application/RenewDueSubscriptions';

function isCardDecline(error: unknown): error is { type: 'StripeCardError'; message: string } {
  return typeof error === 'object' && error !== null && (error as { type?: unknown }).type === 'StripeCardError';
}

export class StripePaymentProcessor implements PaymentProcessor {
  constructor(private readonly stripe: Stripe) {}

  async charge(customerRef: string, paymentMethodRef: string, amountCents: number): Promise<Result<void, ChargeError>> {
    try {
      await this.stripe.paymentIntents.create({
        amount: amountCents, currency: 'usd', customer: customerRef,
        payment_method: paymentMethodRef,
        off_session: true, confirm: true,
      });
      return Result.ok(undefined);
    } catch (error) {
      if (isCardDecline(error)) {
        return Result.fail({ kind: 'Declined', reason: error.message });
      }
      throw error; // infrastructure failures are not counted as declined charges
    }
  }
}
```
A `SequelizeSubscriptionRepository` maps rows to `Subscription` in `findDue` (`status: 'active'`, `renewsAt <= asOf`) and writes `renewsAt`, `failedAttempts` and `status` back in `save`.

#### 4. Scheduler (`src/infrastructure/jobs.ts`)
```typescript
cron.schedule('0 3 * * *', async () => {
  const { renewed, failed } = await renewDueSubscriptions.execute();
  logger.info(`renewals: ${renewed} ok, ${failed} failed`);
});
```

Refactor this Apollo GraphQL resolver for booking clinic appointments. Separate the scheduling rules from Knex and GraphQL:

```typescript
const resolvers = {
  Mutation: {
    bookAppointment: async (_: unknown, args: { doctorId: string; patientId: string; startsAt: string }) => {
      const start = new Date(args.startsAt);
      const end = new Date(start.getTime() + 30 * 60000);
      const hour = start.getUTCHours();
      if (hour < 8 || hour >= 17 || start.getUTCMinutes() % 30 !== 0) {
        throw new GraphQLError('Slot outside working hours', { extensions: { code: 'BAD_SLOT' } });
      }
      const clash = await knex('appointments')
        .where({ doctor_id: args.doctorId })
        .andWhere('starts_at', '<', end)
        .andWhere('ends_at', '>', start)
        .first();
      if (clash) throw new GraphQLError('Slot taken', { extensions: { code: 'SLOT_TAKEN' } });
      const [row] = await knex('appointments')
        .insert({ doctor_id: args.doctorId, patient_id: args.patientId, starts_at: start, ends_at: end })
        .returning('*');
      return row;
    },
  },
};
```

### Architectural Flaws in Original Code
1. **Scheduling policy inside a resolver:** working hours, the 30-minute grid and slot length live next to `GraphQLError`.
2. **Query builder in the API layer:** the overlap rule is expressed only as SQL, so it cannot be tested in memory.
3. **Raw rows returned:** the GraphQL schema is coupled to database column names.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Slot.ts`)
```typescript
import { Result } from '../shared/Result';

export type BookingError = { kind: 'OutsideWorkingHours' } | { kind: 'SlotTaken' };

export class Slot {
  static readonly LENGTH_MINUTES = 30;
  static readonly OPENS_AT_HOUR = 8;
  static readonly CLOSES_AT_HOUR = 17;

  private constructor(readonly start: Date, readonly end: Date) {}

  static at(start: Date): Result<Slot, BookingError> {
    const hour = start.getUTCHours();
    const onGrid = start.getUTCMinutes() % Slot.LENGTH_MINUTES === 0;
    if (hour < Slot.OPENS_AT_HOUR || hour >= Slot.CLOSES_AT_HOUR || !onGrid) {
      return Result.fail({ kind: 'OutsideWorkingHours' });
    }
    return Result.ok(new Slot(start, new Date(start.getTime() + Slot.LENGTH_MINUTES * 60_000)));
  }

  overlaps(other: { start: Date; end: Date }): boolean {
    return other.start < this.end && other.end > this.start;
  }
}

export interface Appointment {
  readonly id?: string;
  readonly doctorId: string;
  readonly patientId: string;
  readonly start: Date;
  readonly end: Date;
}
```

#### 2. Application Layer (`src/application/BookAppointment.ts`)
```typescript
import { Result } from '../shared/Result';
import { Appointment, BookingError, Slot } from '../domain/Slot';

export interface AppointmentRepository {
  forDoctorBetween(doctorId: string, from: Date, to: Date): Promise<Appointment[]>;
  add(appointment: Appointment): Promise<Appointment>;
}

export class BookAppointment {
  constructor(private readonly appointments: AppointmentRepository) {}

  async execute(input: { doctorId: string; patientId: string; startsAt: Date }): Promise<Result<Appointment, BookingError>> {
    const slot = Slot.at(input.startsAt);
    if (!slot.success) return slot;

    const existing = await this.appointments.forDoctorBetween(input.doctorId, slot.data.start, slot.data.end);
    if (existing.some((a) => slot.data.overlaps(a))) return Result.fail({ kind: 'SlotTaken' });

    const booked = await this.appointments.add({
      doctorId: input.doctorId, patientId: input.patientId, start: slot.data.start, end: slot.data.end,
    });
    return Result.ok(booked);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/KnexAppointmentRepository.ts`)
```typescript
import { Knex } from 'knex';
import { Appointment } from '../domain/Slot';
import { AppointmentRepository } from '../application/BookAppointment';

interface AppointmentRow { id: string; doctor_id: string; patient_id: string; starts_at: Date; ends_at: Date; }

const toAppointment = (r: AppointmentRow): Appointment =>
  ({ id: r.id, doctorId: r.doctor_id, patientId: r.patient_id, start: r.starts_at, end: r.ends_at });

export class KnexAppointmentRepository implements AppointmentRepository {
  constructor(private readonly knex: Knex) {}

  async forDoctorBetween(doctorId: string, from: Date, to: Date): Promise<Appointment[]> {
    const rows = await this.knex<AppointmentRow>('appointments')
      .where({ doctor_id: doctorId }).andWhere('starts_at', '<', to).andWhere('ends_at', '>', from);
    return rows.map(toAppointment);
  }

  async add(a: Appointment): Promise<Appointment> {
    const [row] = await this.knex<AppointmentRow>('appointments')
      .insert({ doctor_id: a.doctorId, patient_id: a.patientId, starts_at: a.start, ends_at: a.end })
      .returning('*');
    return toAppointment(row);
  }
}
```

#### 4. Presentation Layer (resolver)
```typescript
function toGraphQLError(error: BookingError): GraphQLError {
  switch (error.kind) {
    case 'OutsideWorkingHours':
      return new GraphQLError('Slot outside working hours', { extensions: { code: 'BAD_SLOT' } });
    case 'SlotTaken':
      return new GraphQLError('Slot taken', { extensions: { code: 'SLOT_TAKEN' } });
  }
}

export const resolvers = {
  Mutation: {
    bookAppointment: async (_: unknown, args: { doctorId: string; patientId: string; startsAt: string }) => {
      const result = await bookAppointment.execute({ ...args, startsAt: new Date(args.startsAt) });
      if (result.success) return result.data;
      throw toGraphQLError(result.error);
    },
  },
};
```

Refactor this Express middleware. The plan quota rules depend directly on Redis and on the request object:

```typescript
export async function quota(req: Request, res: Response, next: NextFunction) {
  const tenant = req.header('x-tenant-id');
  if (!tenant) return res.status(401).json({ error: 'Missing tenant' });
  const plan = (await redis.hget(`tenant:${tenant}`, 'plan')) ?? 'free';
  const limits: Record<string, number> = { free: 1000, pro: 50000, enterprise: Infinity };
  const day = new Date().toISOString().slice(0, 10);
  const key = `usage:${tenant}:${day}`;
  const used = await redis.incr(key);
  if (used === 1) await redis.expire(key, 86400);
  const limit = limits[plan] ?? 1000;
  res.setHeader('X-RateLimit-Remaining', String(Math.max(0, limit - used)));
  if (used > limit) return res.status(429).json({ error: 'Daily quota exceeded', plan });
  next();
}
```

### Architectural Flaws in Original Code
1. **Plan policy inside middleware:** the daily limits per plan cannot be changed or tested without Express and Redis.
2. **Storage keys mixed with rules:** counter naming and TTL handling sit next to the quota decision.
3. **Unknown plans fall back silently** through an untyped string lookup.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/quota.ts`)
```typescript
export type Plan = 'free' | 'pro' | 'enterprise';

const DAILY_LIMITS: { readonly [P in Plan]: number } = {
  free: 1000,
  pro: 50_000,
  enterprise: Infinity,
};

export function toPlan(value: string | null): Plan {
  return value === 'pro' || value === 'enterprise' ? value : 'free';
}

export interface QuotaDecision {
  readonly allowed: boolean;
  readonly remaining: number;
  readonly plan: Plan;
}

export function decide(plan: Plan, usedToday: number): QuotaDecision {
  const limit = DAILY_LIMITS[plan];
  return { allowed: usedToday <= limit, remaining: Math.max(0, limit - usedToday), plan };
}
```

#### 2. Application Layer (`src/application/ConsumeQuota.ts`)
```typescript
import { Result } from '../shared/Result';
import { Plan, QuotaDecision, decide } from '../domain/quota';

export type QuotaError = { kind: 'MissingTenant' };

export interface TenantPlans {
  planOf(tenantId: string): Promise<Plan>;
}

export interface UsageCounter {
  /** Increments and returns today's request count for the tenant. */
  increment(tenantId: string, day: string): Promise<number>;
}

export class ConsumeQuota {
  constructor(
    private readonly plans: TenantPlans,
    private readonly usage: UsageCounter,
    private readonly today: () => string,
  ) {}

  async execute(tenantId: string | undefined): Promise<Result<QuotaDecision, QuotaError>> {
    if (!tenantId) return Result.fail({ kind: 'MissingTenant' });
    const plan = await this.plans.planOf(tenantId);
    const used = await this.usage.increment(tenantId, this.today());
    return Result.ok(decide(plan, used));
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/redisQuota.ts`)
```typescript
import type { Redis } from 'ioredis';
import { Plan, toPlan } from '../domain/quota';
import { TenantPlans, UsageCounter } from '../application/ConsumeQuota';

export class RedisTenantPlans implements TenantPlans {
  constructor(private readonly redis: Redis) {}

  async planOf(tenantId: string): Promise<Plan> {
    return toPlan(await this.redis.hget(`tenant:${tenantId}`, 'plan'));
  }
}

export class RedisUsageCounter implements UsageCounter {
  constructor(private readonly redis: Redis) {}

  async increment(tenantId: string, day: string): Promise<number> {
    const key = `usage:${tenantId}:${day}`;
    const used = await this.redis.incr(key);
    if (used === 1) await this.redis.expire(key, 86_400);
    return used;
  }
}
```

#### 4. Presentation Layer (`src/http/quotaMiddleware.ts`)
```typescript
import { NextFunction, Request, Response } from 'express';
import { ConsumeQuota } from '../application/ConsumeQuota';

export function quotaMiddleware(consumeQuota: ConsumeQuota) {
  return async (req: Request, res: Response, next: NextFunction) => {
    const result = await consumeQuota.execute(req.header('x-tenant-id'));
    if (!result.success) return res.status(401).json({ error: 'Missing tenant' });

    const { allowed, remaining, plan } = result.data;
    res.setHeader('X-RateLimit-Remaining', String(remaining));
    if (!allowed) return res.status(429).json({ error: 'Daily quota exceeded', plan });
    next();
  };
}
```
Wiring: `app.use(quotaMiddleware(new ConsumeQuota(plans, usage, () => new Date().toISOString().slice(0, 10))))`.

In this Angular service the seat selection rules are mixed with HttpClient calls. Apply Clean Architecture so the rules have no Angular dependency:

```typescript
@Injectable({ providedIn: 'root' })
export class SeatService {
  constructor(private http: HttpClient) {}

  async select(flightId: string, seat: string, passenger: { age: number; tier: string }) {
    const map = await firstValueFrom(this.http.get<any>(`/api/flights/${flightId}/seats`));
    const s = map.seats.find((x: any) => x.code === seat);
    if (!s || s.taken) throw new Error('Seat not available');
    if (s.exitRow && passenger.age < 15) throw new Error('Exit row requires age 15+');
    let fee = 0;
    if (s.extraLegroom) fee = passenger.tier === 'gold' ? 0 : 35;
    else if (s.row <= 5) fee = passenger.tier === 'gold' ? 0 : 20;
    await firstValueFrom(this.http.post(`/api/flights/${flightId}/seats/${seat}`, { fee }));
    return fee;
  }
}
```

### Architectural Flaws in Original Code
1. **Business rules in a framework service:** exit-row age limits and seat fees depend on `@Injectable` and `HttpClient`.
2. **`any` everywhere:** the seat map is untyped, so a renamed field breaks silently.
3. **Errors as thrown strings:** callers cannot tell "seat taken" from "age restriction" without parsing messages.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/seating.ts`)
```typescript
import { Result } from '../shared/Result';

export type LoyaltyTier = 'standard' | 'silver' | 'gold';

export interface Seat {
  readonly code: string;
  readonly row: number;
  readonly taken: boolean;
  readonly exitRow: boolean;
  readonly extraLegroom: boolean;
}

export interface Passenger {
  readonly age: number;
  readonly tier: LoyaltyTier;
}

export type SeatError =
  | { kind: 'SeatUnavailable'; seat: string }
  | { kind: 'ExitRowAgeRestriction'; minimumAge: number };

export const EXIT_ROW_MIN_AGE = 15;

export function seatFee(seat: Seat, passenger: Passenger): Result<number, SeatError> {
  if (seat.taken) return Result.fail({ kind: 'SeatUnavailable', seat: seat.code });
  if (seat.exitRow && passenger.age < EXIT_ROW_MIN_AGE) {
    return Result.fail({ kind: 'ExitRowAgeRestriction', minimumAge: EXIT_ROW_MIN_AGE });
  }
  if (passenger.tier === 'gold') return Result.ok(0);
  if (seat.extraLegroom) return Result.ok(35);
  if (seat.row <= 5) return Result.ok(20);
  return Result.ok(0);
}
```

#### 2. Application Layer (`src/application/SelectSeat.ts`)
```typescript
import { Result } from '../shared/Result';
import { Passenger, Seat, SeatError, seatFee } from '../domain/seating';

export interface SeatMapSource {
  seats(flightId: string): Promise<Seat[]>;
  assign(flightId: string, seatCode: string, fee: number): Promise<void>;
}

export class SelectSeat {
  constructor(private readonly seatMap: SeatMapSource) {}

  async execute(flightId: string, seatCode: string, passenger: Passenger): Promise<Result<number, SeatError>> {
    const seat = (await this.seatMap.seats(flightId)).find((s) => s.code === seatCode);
    if (!seat) return Result.fail({ kind: 'SeatUnavailable', seat: seatCode });

    const fee = seatFee(seat, passenger);
    if (!fee.success) return fee;

    await this.seatMap.assign(flightId, seatCode, fee.data);
    return fee;
  }
}
