This release CLI decides the next version from git commits. Refactor it so the versioning rules are independent of git, yargs and the filesystem:

```typescript
const argv = yargs(hideBin(process.argv)).option('dry-run', { type: 'boolean' }).parseSync();
const git = simpleGit();
const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
const lastTag = (await git.tags()).latest ?? 'v0.0.0';
const log = await git.log({ from: lastTag, to: 'HEAD' });
let bump = 'none';
for (const c of log.all) {
  if (/BREAKING CHANGE/.test(c.body) || /^\w+(\(.+\))?!:/.test(c.message)) { bump = 'major'; break; }
  if (/^feat(\(.+\))?:/.test(c.message)) bump = 'minor';
  else if (/^fix(\(.+\))?:/.test(c.message) && bump === 'none') bump = 'patch';
}
if (bump === 'none') { console.log('Nothing to release'); process.exit(0); }
const [maj, min, pat] = pkg.version.split('.').map(Number);
const next = bump === 'major' ? `${maj + 1}.0.0` : bump === 'minor' ? `${maj}.${min + 1}.0` : `${maj}.${min}.${pat + 1}`;
if (!argv['dry-run']) {
  pkg.version = next;
  fs.writeFileSync('package.json', JSON.stringify(pkg, null, 2) + '\n');
  await git.addTag(`v${next}`);
}
console.log(`Next version: ${next}`);
```

### Architectural Flaws in Original Code
1. **Versioning policy in a script body:** the Conventional Commits rules cannot be tested without a git repository.
2. **Tooling everywhere:** `yargs`, `simple-git` and `fs` are used in the same flow that decides the bump.
3. **`process.exit` in the middle of logic** makes the flow impossible to reuse from another command.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/version.ts`)
```typescript
export type Bump = 'none' | 'patch' | 'minor' | 'major';

export interface Commit {
  readonly subject: string;
  readonly body: string;
}

const RANK: { readonly [B in Bump]: number } = { none: 0, patch: 1, minor: 2, major: 3 };

export function bumpFor(commit: Commit): Bump {
  if (/BREAKING CHANGE/.test(commit.body) || /^\w+(\(.+\))?!:/.test(commit.subject)) return 'major';
  if (/^feat(\(.+\))?:/.test(commit.subject)) return 'minor';
  if (/^fix(\(.+\))?:/.test(commit.subject)) return 'patch';
  return 'none';
}

export function releaseBump(commits: readonly Commit[]): Bump {
  return commits.map(bumpFor).reduce<Bump>((a, b) => (RANK[b] > RANK[a] ? b : a), 'none');
}

export function nextVersion(current: string, bump: Exclude<Bump, 'none'>): string {
  const [major, minor, patch] = current.split('.').map(Number);
  if (bump === 'major') return `${major + 1}.0.0`;
  if (bump === 'minor') return `${major}.${minor + 1}.0`;
  return `${major}.${minor}.${patch + 1}`;
}
```

#### 2. Application Layer (`src/application/PrepareRelease.ts`)
```typescript
import { Result } from '../shared/Result';
import { Commit, nextVersion, releaseBump } from '../domain/version';

export type ReleaseError = { kind: 'NothingToRelease' };

export interface Repository {
  latestTag(): Promise<string | null>;
  commitsSince(tag: string): Promise<Commit[]>;
  tag(name: string): Promise<void>;
}

export interface Manifest {
  currentVersion(): Promise<string>;
  setVersion(version: string): Promise<void>;
}

export class PrepareRelease {
  constructor(private readonly repo: Repository, private readonly manifest: Manifest) {}

  async execute(options: { dryRun: boolean }): Promise<Result<string, ReleaseError>> {
    const since = (await this.repo.latestTag()) ?? 'v0.0.0';
    const bump = releaseBump(await this.repo.commitsSince(since));
    if (bump === 'none') return Result.fail({ kind: 'NothingToRelease' });

    const next = nextVersion(await this.manifest.currentVersion(), bump);
    if (!options.dryRun) {
      await this.manifest.setVersion(next);
      await this.repo.tag(`v${next}`);
    }
    return Result.ok(next);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure`)
```typescript
import { readFile, writeFile } from 'node:fs/promises';
import { SimpleGit } from 'simple-git';
import { Commit } from '../domain/version';
import { Manifest, Repository } from '../application/PrepareRelease';

export class SimpleGitRepository implements Repository {
  constructor(private readonly git: SimpleGit) {}
  async latestTag(): Promise<string | null> { return (await this.git.tags()).latest ?? null; }
  async commitsSince(tag: string): Promise<Commit[]> {
    const log = await this.git.log({ from: tag, to: 'HEAD' });
    return log.all.map((c) => ({ subject: c.message, body: c.body }));
  }
  async tag(name: string): Promise<void> { await this.git.addTag(name); }
}

export class PackageJsonManifest implements Manifest {
  constructor(private readonly path = 'package.json') {}
  async currentVersion(): Promise<string> {
    return (JSON.parse(await readFile(this.path, 'utf8')) as { version: string }).version;
  }
  async setVersion(version: string): Promise<void> {
    const pkg = JSON.parse(await readFile(this.path, 'utf8')) as Record<string, unknown>;
    await writeFile(this.path, JSON.stringify({ ...pkg, version }, null, 2) + '\n');
  }
}
```

#### 4. CLI Entry Point (`src/cli.ts`)
```typescript
const argv = yargs(hideBin(process.argv)).option('dry-run', { type: 'boolean', default: false }).parseSync();
const release = new PrepareRelease(new SimpleGitRepository(simpleGit()), new PackageJsonManifest());
const result = await release.execute({ dryRun: argv['dry-run'] });
console.log(result.success ? `Next version: ${result.data}` : 'Nothing to release');
```

Decouple the bidding rules in this Socket.IO handler from MongoDB and the socket layer:

```typescript
io.on('connection', (socket) => {
  socket.on('bid', async ({ auctionId, bidderId, amount }) => {
    const auction = await db.collection('auctions').findOne({ _id: new ObjectId(auctionId) });
    if (!auction) return socket.emit('bid:error', 'Auction not found');
    if (Date.now() > auction.endsAt.getTime()) return socket.emit('bid:error', 'Auction closed');
    if (auction.sellerId === bidderId) return socket.emit('bid:error', 'Sellers cannot bid');
    const current = auction.highestBid ?? auction.startingPrice;
    const step = current < 100 ? 1 : current < 1000 ? 10 : 50;
    if (amount < current + step) return socket.emit('bid:error', `Minimum bid is ${current + step}`);
    let endsAt = auction.endsAt;
    if (auction.endsAt.getTime() - Date.now() < 120000) endsAt = new Date(Date.now() + 120000);
    await db.collection('auctions').updateOne({ _id: auction._id },
      { $set: { highestBid: amount, highestBidderId: bidderId, endsAt } });
    io.to(auctionId).emit('bid:accepted', { amount, bidderId, endsAt });
  });
});
```

### Architectural Flaws in Original Code
1. **Auction rules live in a socket listener:** bid increments, seller restrictions and the anti-sniping extension depend on Socket.IO.
2. **Persistence and broadcasting mixed with decisions:** MongoDB updates and room emits are interleaved with validation.
3. **Clock read four times:** `Date.now()` is called repeatedly, so a single bid can see different "now" values.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Auction.ts`)
```typescript
import { Result } from '../shared/Result';

export type BidError =
  | { kind: 'AuctionNotFound' }
  | { kind: 'AuctionClosed' }
  | { kind: 'SellerCannotBid' }
  | { kind: 'BidTooLow'; minimum: number };

export interface AcceptedBid { readonly amount: number; readonly bidderId: string; readonly endsAt: Date; }

export class Auction {
  static readonly EXTENSION_MS = 120_000;

  constructor(
    readonly id: string,
    readonly sellerId: string,
    readonly startingPrice: number,
    private endTime: Date,
    private highest: { amount: number; bidderId: string } | null,
  ) {}

  get endsAt(): Date { return this.endTime; }

  minimumNextBid(): number {
    const current = this.highest?.amount ?? this.startingPrice;
    const step = current < 100 ? 1 : current < 1000 ? 10 : 50;
    return current + step;
  }

  placeBid(bidderId: string, amount: number, now: Date): Result<AcceptedBid, BidError> {
    if (now > this.endTime) return Result.fail({ kind: 'AuctionClosed' });
    if (bidderId === this.sellerId) return Result.fail({ kind: 'SellerCannotBid' });
    const minimum = this.minimumNextBid();
    if (amount < minimum) return Result.fail({ kind: 'BidTooLow', minimum });

    this.highest = { amount, bidderId };
    if (this.endTime.getTime() - now.getTime() < Auction.EXTENSION_MS) {
      this.endTime = new Date(now.getTime() + Auction.EXTENSION_MS); // anti-sniping
    }
    return Result.ok({ amount, bidderId, endsAt: this.endTime });
  }
}
```

#### 2. Application Layer (`src/application/PlaceBid.ts`)
```typescript
import { Result } from '../shared/Result';
import { AcceptedBid, Auction, BidError } from '../domain/Auction';

export interface AuctionRepository {
  findById(id: string): Promise<Auction | null>;
  saveBid(auction: Auction, bid: AcceptedBid): Promise<void>;
}

export interface BidBroadcaster {
  accepted(auctionId: string, bid: AcceptedBid): void;
}

export class PlaceBid {
  constructor(
    private readonly auctions: AuctionRepository,
    private readonly broadcaster: BidBroadcaster,
    private readonly clock: () => Date,
  ) {}

  async execute(auctionId: string, bidderId: string, amount: number): Promise<Result<AcceptedBid, BidError>> {
    const auction = await this.auctions.findById(auctionId);
    if (!auction) return Result.fail({ kind: 'AuctionNotFound' });

    const bid = auction.placeBid(bidderId, amount, this.clock());
    if (!bid.success) return bid;

    await this.auctions.saveBid(auction, bid.data);
    this.broadcaster.accepted(auctionId, bid.data);
    return bid;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure`)
```typescript
import { Collection, ObjectId } from 'mongodb';
import { Server } from 'socket.io';

interface AuctionDoc {
  _id: ObjectId; sellerId: string; startingPrice: number; endsAt: Date;
  highestBid?: number; highestBidderId?: string;
}

export class MongoAuctionRepository implements AuctionRepository {
  constructor(private readonly auctions: Collection<AuctionDoc>) {}

  async findById(id: string): Promise<Auction | null> {
    const d = await this.auctions.findOne({ _id: new ObjectId(id) });
    if (!d) return null;
    const highest = d.highestBid !== undefined && d.highestBidderId !== undefined
      ? { amount: d.highestBid, bidderId: d.highestBidderId } : null;
    return new Auction(id, d.sellerId, d.startingPrice, d.endsAt, highest);
  }

  async saveBid(auction: Auction, bid: AcceptedBid): Promise<void> {
    await this.auctions.updateOne({ _id: new ObjectId(auction.id) },
      { $set: { highestBid: bid.amount, highestBidderId: bid.bidderId, endsAt: bid.endsAt } });
  }
}

export class SocketBidBroadcaster implements BidBroadcaster {
  constructor(private readonly io: Server) {}
  accepted(auctionId: string, bid: AcceptedBid): void { this.io.to(auctionId).emit('bid:accepted', bid); }
}
```

#### 4. Presentation Layer (socket handler)
```typescript
function describe(error: BidError): string {
  switch (error.kind) {
    case 'AuctionNotFound': return 'Auction not found';
    case 'AuctionClosed': return 'Auction closed';
    case 'SellerCannotBid': return 'Sellers cannot bid';
    case 'BidTooLow': return `Minimum bid is ${error.minimum}`;
