Apply Clean Architecture to this Cloudflare Worker (Hono + KV) that creates short links:

```typescript
const app = new Hono<{ Bindings: { LINKS: KVNamespace } }>();

app.post('/links', async (c) => {
  const { url, alias, ttlDays } = await c.req.json();
  let target: URL;
  try { target = new URL(url); } catch { return c.json({ error: 'Invalid URL' }, 400); }
  if (target.protocol !== 'https:') return c.json({ error: 'Only https links' }, 400);
  const reserved = ['admin', 'api', 'links'];
  const slug = alias ?? Math.random().toString(36).slice(2, 8);
  if (!/^[a-z0-9-]{3,32}$/.test(slug) || reserved.includes(slug)) {
    return c.json({ error: 'Invalid alias' }, 400);
  }
  if (await c.env.LINKS.get(slug)) return c.json({ error: 'Alias taken' }, 409);
  const days = Math.min(ttlDays ?? 30, 365);
  await c.env.LINKS.put(slug, target.toString(), { expirationTtl: days * 86400 });
  return c.json({ slug, expiresInDays: days }, 201);
});
```

### Architectural Flaws in Original Code
1. **Link policy tied to the Worker runtime:** https-only, alias format, reserved words and the TTL cap need Hono and KV to run.
2. **Randomness is hidden:** `Math.random()` inside the handler makes generated slugs untestable.
3. **Untyped body:** `c.req.json()` is destructured without validation.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/ShortLink.ts`)
```typescript
import { Result } from '../shared/Result';

export type LinkError =
  | { kind: 'InvalidUrl' }
  | { kind: 'InsecureUrl' }
  | { kind: 'InvalidAlias' }
  | { kind: 'AliasTaken' };

const RESERVED = new Set(['admin', 'api', 'links']);
const SLUG = /^[a-z0-9-]{3,32}$/;
export const DEFAULT_TTL_DAYS = 30;
export const MAX_TTL_DAYS = 365;

export interface ShortLink {
  readonly slug: string;
  readonly target: string;
  readonly ttlDays: number;
}

export function createShortLink(input: { url: string; slug: string; ttlDays?: number }): Result<ShortLink, LinkError> {
  let target: URL;
  try {
    target = new URL(input.url);
  } catch {
    return Result.fail({ kind: 'InvalidUrl' });
  }
  if (target.protocol !== 'https:') return Result.fail({ kind: 'InsecureUrl' });
  if (!SLUG.test(input.slug) || RESERVED.has(input.slug)) return Result.fail({ kind: 'InvalidAlias' });
  const ttlDays = Math.min(input.ttlDays ?? DEFAULT_TTL_DAYS, MAX_TTL_DAYS);
  return Result.ok({ slug: input.slug, target: target.toString(), ttlDays });
}
```

#### 2. Application Layer (`src/application/ShortenLink.ts`)
```typescript
import { Result } from '../shared/Result';
import { LinkError, ShortLink, createShortLink } from '../domain/ShortLink';

export interface LinkStore {
  exists(slug: string): Promise<boolean>;
  save(link: ShortLink): Promise<void>;
}

export interface SlugGenerator {
  next(): string;
}

export class ShortenLink {
  constructor(private readonly links: LinkStore, private readonly slugs: SlugGenerator) {}

  async execute(input: { url: string; alias?: string; ttlDays?: number }): Promise<Result<ShortLink, LinkError>> {
    const link = createShortLink({ url: input.url, slug: input.alias ?? this.slugs.next(), ttlDays: input.ttlDays });
    if (!link.success) return link;
    if (await this.links.exists(link.data.slug)) return Result.fail({ kind: 'AliasTaken' });
    await this.links.save(link.data);
    return link;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/kv.ts`)
```typescript
import { ShortLink } from '../domain/ShortLink';
import { LinkStore, SlugGenerator } from '../application/ShortenLink';

export class KvLinkStore implements LinkStore {
  constructor(private readonly kv: KVNamespace) {}

  async exists(slug: string): Promise<boolean> {
    return (await this.kv.get(slug)) !== null;
  }

  async save(link: ShortLink): Promise<void> {
    await this.kv.put(link.slug, link.target, { expirationTtl: link.ttlDays * 86_400 });
  }
}

export const randomSlugs: SlugGenerator = { next: () => Math.random().toString(36).slice(2, 8) };
```

#### 4. Presentation Layer (`src/worker.ts`)
```typescript
function toHttp(error: LinkError): [400 | 409, string] {
  switch (error.kind) {
    case 'InvalidUrl': return [400, 'Invalid URL'];
    case 'InsecureUrl': return [400, 'Only https links'];
    case 'InvalidAlias': return [400, 'Invalid alias'];
    case 'AliasTaken': return [409, 'Alias taken'];
  }
}

const app = new Hono<{ Bindings: { LINKS: KVNamespace } }>();

app.post('/links', async (c) => {
  const body = (await c.req.json()) as { url?: unknown; alias?: unknown; ttlDays?: unknown };
  if (typeof body.url !== 'string') return c.json({ error: 'Invalid URL' }, 400);

  const shorten = new ShortenLink(new KvLinkStore(c.env.LINKS), randomSlugs);
  const result = await shorten.execute({
    url: body.url,
    alias: typeof body.alias === 'string' ? body.alias : undefined,
    ttlDays: typeof body.ttlDays === 'number' ? body.ttlDays : undefined,
  });
  if (result.success) return c.json({ slug: result.data.slug, expiresInDays: result.data.ttlDays }, 201);
  const [status, error] = toHttp(result.error);
  return c.json({ error }, status);
});
```

Our order status transitions are implemented as Mongoose schema methods and a pre-save hook. Move the business rules out of the persistence model:

```typescript
const orderSchema = new Schema({
  status: { type: String, default: 'pending' },
  items: [{ sku: String, qty: Number }],
  shippedAt: Date,
  cancelReason: String,
});

orderSchema.methods.transition = function (to: string, reason?: string) {
  const allowed: Record<string, string[]> = {
    pending: ['paid', 'cancelled'],
    paid: ['shipped', 'cancelled'],
    shipped: ['delivered'],
  };
  if (!(allowed[this.status] ?? []).includes(to)) throw new Error(`Cannot go from ${this.status} to ${to}`);
  if (to === 'cancelled' && !reason) throw new Error('Cancellation needs a reason');
  this.status = to;
  if (to === 'cancelled') this.cancelReason = reason;
};

orderSchema.pre('save', function (next) {
  if (this.isModified('status') && this.status === 'shipped') this.shippedAt = new Date();
  next();
});

export const OrderModel = model('Order', orderSchema);
```

### Architectural Flaws in Original Code
1. **State machine inside the ORM:** transition rules only exist on Mongoose documents, so they cannot run without a schema.
2. **Hidden side effect in a hook:** `shippedAt` is set by `pre('save')`, far from the rule that triggers it.
3. **Stringly typed status and thrown errors** give callers no compile-time safety.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Order.ts`)
```typescript
import { Result } from '../shared/Result';

export type OrderStatus = 'pending' | 'paid' | 'shipped' | 'delivered' | 'cancelled';

export type TransitionError =
  | { kind: 'InvalidTransition'; from: OrderStatus; to: OrderStatus }
  | { kind: 'ReasonRequired' };

const ALLOWED: { readonly [S in OrderStatus]: readonly OrderStatus[] } = {
  pending: ['paid', 'cancelled'],
  paid: ['shipped', 'cancelled'],
  shipped: ['delivered'],
  delivered: [],
  cancelled: [],
};

export interface OrderLine { readonly sku: string; readonly qty: number; }

export interface OrderState {
  readonly status: OrderStatus;
  readonly shippedAt?: Date;
  readonly cancelReason?: string;
}

export class Order {
  constructor(readonly id: string, readonly lines: readonly OrderLine[], private current: OrderState) {}

  get state(): OrderState { return this.current; }

  transition(to: OrderStatus, now: Date, reason?: string): Result<OrderState, TransitionError> {
    const from = this.current.status;
    if (!ALLOWED[from].includes(to)) return Result.fail({ kind: 'InvalidTransition', from, to });
    if (to === 'cancelled' && !reason) return Result.fail({ kind: 'ReasonRequired' });

    this.current = {
      ...this.current,
      status: to,
      shippedAt: to === 'shipped' ? now : this.current.shippedAt,
      cancelReason: to === 'cancelled' ? reason : this.current.cancelReason,
    };
    return Result.ok(this.current);
  }
}
```

#### 2. Application Layer (`src/application/ChangeOrderStatus.ts`)
```typescript
import { Result } from '../shared/Result';
import { Order, OrderState, OrderStatus, TransitionError } from '../domain/Order';

export type ChangeStatusError = TransitionError | { kind: 'OrderNotFound' };

export interface OrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

export class ChangeOrderStatus {
  constructor(private readonly orders: OrderRepository, private readonly clock: () => Date) {}

  async execute(orderId: string, to: OrderStatus, reason?: string): Promise<Result<OrderState, ChangeStatusError>> {
    const order = await this.orders.findById(orderId);
    if (!order) return Result.fail({ kind: 'OrderNotFound' });

    const changed = order.transition(to, this.clock(), reason);
    if (!changed.success) return changed;

    await this.orders.save(order);
    return changed;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/MongooseOrderRepository.ts`)
The schema becomes a plain persistence mapping with no methods or hooks.
```typescript
import { Model, Schema, Types, model } from 'mongoose';
import { Order, OrderStatus } from '../domain/Order';
import { OrderRepository } from '../application/ChangeOrderStatus';

interface OrderDoc {
  _id: Types.ObjectId;
  status: OrderStatus;
  items: { sku: string; qty: number }[];
  shippedAt?: Date;
  cancelReason?: string;
}

const orderSchema = new Schema<OrderDoc>({
  status: { type: String, default: 'pending' },
  items: [{ sku: String, qty: Number }],
  shippedAt: Date,
  cancelReason: String,
});

export const OrderModel: Model<OrderDoc> = model<OrderDoc>('Order', orderSchema);

export class MongooseOrderRepository implements OrderRepository {
  async findById(id: string): Promise<Order | null> {
    const doc = await OrderModel.findById(id).lean<OrderDoc>();
    if (!doc) return null;
    return new Order(doc._id.toString(), doc.items, {
      status: doc.status, shippedAt: doc.shippedAt, cancelReason: doc.cancelReason,
    });
  }

  async save(order: Order): Promise<void> {
    await OrderModel.updateOne({ _id: new Types.ObjectId(order.id) }, { $set: { ...order.state } });
  }
}
```

Callers now receive `{ kind: 'InvalidTransition', from: 'shipped', to: 'cancelled' }` instead of parsing an error message, and `shippedAt` is set by the same rule that ships the order.

Separate the one-time-code rules in these two Express routes from Twilio and Redis:

```typescript
app.post('/otp/send', async (req, res) => {
  const phone = String(req.body.phone).replace(/\s+/g, '');
  if (!/^\+[1-9]\d{7,14}$/.test(phone)) return res.status(400).json({ error: 'Invalid phone' });
  const code = String(Math.floor(100000 + Math.random() * 900000));
  await redis.set(`otp:${phone}`, JSON.stringify({ code, attempts: 0 }), 'EX', 300);
  await twilio.messages.create({ to: phone, from: process.env.TWILIO_FROM, body: `Your code is ${code}` });
  res.status(202).end();
});

app.post('/otp/verify', async (req, res) => {
  const phone = String(req.body.phone).replace(/\s+/g, '');
  const raw = await redis.get(`otp:${phone}`);
  if (!raw) return res.status(410).json({ error: 'Code expired' });
  const otp = JSON.parse(raw);
  if (otp.attempts >= 5) return res.status(429).json({ error: 'Too many attempts' });
  if (otp.code !== req.body.code) {
    await redis.set(`otp:${phone}`, JSON.stringify({ ...otp, attempts: otp.attempts + 1 }), 'KEEPTTL');
    return res.status(401).json({ error: 'Wrong code' });
  }
  await redis.del(`otp:${phone}`);
  res.json({ verified: true });
});
```

### Architectural Flaws in Original Code
1. **Verification policy split across routes:** phone format, code length, five attempts and the five-minute expiry live in HTTP callbacks.
2. **Vendor calls inline:** Twilio and Redis are used directly, so neither flow can run in a test.
3. **Duplicated normalisation:** the phone clean-up is copy-pasted in both handlers.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/otp.ts`)
```typescript
import { Result } from '../shared/Result';

export type OtpError =
  | { kind: 'InvalidPhone' }
  | { kind: 'Expired' }
  | { kind: 'TooManyAttempts' }
  | { kind: 'WrongCode' };

export class PhoneNumber {
  private constructor(readonly value: string) {}

  static parse(raw: string): Result<PhoneNumber, OtpError> {
    const value = raw.replace(/\s+/g, '');
    return /^\+[1-9]\d{7,14}$/.test(value) ? Result.ok(new PhoneNumber(value)) : Result.fail({ kind: 'InvalidPhone' });
  }
}

export const OTP_TTL_SECONDS = 300;
export const MAX_ATTEMPTS = 5;

export interface PendingCode {
  readonly code: string;
  readonly attempts: number;
}

/** Returns the state to store after a wrong guess, or null when the code matched. */
export function checkCode(pending: PendingCode, guess: string): Result<PendingCode | null, OtpError> {
  if (pending.attempts >= MAX_ATTEMPTS) return Result.fail({ kind: 'TooManyAttempts' });
  if (pending.code !== guess) return Result.ok({ ...pending, attempts: pending.attempts + 1 });
  return Result.ok(null);
}
```

#### 2. Application Layer (`src/application/otp.ts`)
```typescript
import { Result } from '../shared/Result';
import { OTP_TTL_SECONDS, OtpError, PendingCode, PhoneNumber, checkCode } from '../domain/otp';

export interface CodeStore {
  put(phone: PhoneNumber, pending: PendingCode, ttlSeconds: number): Promise<void>;
  get(phone: PhoneNumber): Promise<PendingCode | null>;
  update(phone: PhoneNumber, pending: PendingCode): Promise<void>; // keeps the TTL
  remove(phone: PhoneNumber): Promise<void>;
}

export interface TextMessenger {
  send(to: PhoneNumber, text: string): Promise<void>;
}

export class OneTimeCodes {
  constructor(
    private readonly store: CodeStore,
    private readonly messenger: TextMessenger,
    private readonly generate: () => string,
  ) {}

  async send(rawPhone: string): Promise<Result<void, OtpError>> {
    const phone = PhoneNumber.parse(rawPhone);
    if (!phone.success) return phone;
    const code = this.generate();
    await this.store.put(phone.data, { code, attempts: 0 }, OTP_TTL_SECONDS);
    await this.messenger.send(phone.data, `Your code is ${code}`);
    return Result.ok(undefined);
  }

  async verify(rawPhone: string, guess: string): Promise<Result<void, OtpError>> {
    const phone = PhoneNumber.parse(rawPhone);
    if (!phone.success) return phone;
    const pending = await this.store.get(phone.data);
    if (!pending) return Result.fail({ kind: 'Expired' });

    const checked = checkCode(pending, guess);
    if (!checked.success) return checked;
    if (checked.data) {
      await this.store.update(phone.data, checked.data);
      return Result.fail({ kind: 'WrongCode' });
    }
    await this.store.remove(phone.data);
    return Result.ok(undefined);
  }
}
```

#### 3. Infrastructure Layer
`RedisCodeStore` keeps the `otp:<phone>` key with `EX` / `KEEPTTL`, and the messenger wraps Twilio:
```typescript
import { Twilio } from 'twilio';

export class TwilioMessenger implements TextMessenger {
  constructor(private readonly client: Twilio, private readonly from: string) {}

  async send(to: PhoneNumber, text: string): Promise<void> {
    await this.client.messages.create({ to: to.value, from: this.from, body: text });
  }
}

export const sixDigits = (): string => String(Math.floor(100000 + Math.random() * 900000));
```

#### 4. Presentation Layer
```typescript
function toHttp(error: OtpError): [number, string] {
  switch (error.kind) {
    case 'InvalidPhone': return [400, 'Invalid phone'];
    case 'Expired': return [410, 'Code expired'];
    case 'TooManyAttempts': return [429, 'Too many attempts'];
    case 'WrongCode': return [401, 'Wrong code'];
  }
}

app.post('/otp/send', async (req, res) => {
  const result = await otp.send(String(req.body.phone));
  if (result.success) return res.status(202).end();
  const [status, error] = toHttp(result.error);
  res.status(status).json({ error });
});

app.post('/otp/verify', async (req, res) => {
  const result = await otp.verify(String(req.body.phone), String(req.body.code));
  if (result.success) return res.json({ verified: true });
  const [status, error] = toHttp(result.error);
